SINA_SMART["genetics1-heredity"] = {"lecture":"genetics1-heredity","title":"Hereditary disease transmission","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"genetics1-heredity:e0","text":"6-8% of births have a genetic anomaly; Morocco: 74% of genetic disorders AR.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-heredity:e1","text":"Congenital ≠ always genetic.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-heredity:e2","text":"Co-dominance: ABO; incomplete dominance: intermediate phenotype.","topic":"Key terms","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-heredity:e3","text":"AD: vertical, 50%, both sexes; de novo, germline mosaicism, incomplete penetrance (retinoblastoma ~90%).","topic":"Autosomal dominant and recessive","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-heredity:e4","text":"AD examples: achondroplasia, NF1, Marfan, ADPKD, osteogenesis imperfecta.","topic":"Autosomal dominant and recessive","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-heredity:e5","text":"AR: horizontal, carrier parents, 25% risk, consanguinity; CF, thalassaemia, Wilson, SMA.","topic":"Autosomal dominant and recessive","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-heredity:e10","text":"Multifactorial: liability threshold; imprinting: parent-of-origin expression.","topic":"X-linked and non-Mendelian inheritance","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-heredity:e6","text":"XR: males, no father→son; haemophilia A/B, DMD, colour blindness.","topic":"X-linked and non-Mendelian inheritance","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-heredity:e7","text":"XD: affected father → all daughters; fragile X, hypophosphataemic rickets.","topic":"X-linked and non-Mendelian inheritance","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-heredity:e8","text":"Y-linked: father → all sons.","topic":"X-linked and non-Mendelian inheritance","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-heredity:e9","text":"Mitochondrial: maternal; heteroplasmy.","topic":"X-linked and non-Mendelian inheritance","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"rw4z6s":"a","fjfrrt":"a","zy8tk0":"a","1fobit3":"a","cpvn5c":"a","112siss":"a","os40o7":"a","1toxtbe":"a","1dn5mh8":"a","fa89d8":"a","1q7nl8n":"a","11xsu7t":"a","1vifo28":"a","1vsxnya":"a","1ecqdu9":"a","ucsyl3":"a","1lci8x5":"a","1vxqo8x":"x"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"genetics1-heredity:e0":{"s":0,"u":["6-8% of births have a genetic anomaly; Morocco: 74% of genetic disorders AR.","In Morocco , about 74% of genetic disorders are autosomal recessive , 17% autosomal dominant, 5% X-linked, 0.4% mitochondrial and 0.4% Y-linked.","About 6-8% of births worldwide involve a genetic or partly genetic anomaly; chromosomal anomalies explain ~11% of recurrent pregnancy loss in Moroccan couples."],"dp":[{"h":"Why consanguinity raises recessive disease","t":"Relatives share a common ancestor and therefore some identical alleles. If that ancestor carried a rare recessive mutation, two cousins are far more likely than two unrelated people to both carry it, so their child has a real chance of inheriting two copies. This is why autosomal recessive disorders dominate Morocco's genetic disease profile. Source: the lecture's consanguinity slide and Moroccan statistics."}]},"genetics1-heredity:e1":{"s":0,"u":["Congenital ≠ always genetic.","Medical genetics studies heredity and the genetic causes of disease: diagnosis and management, genetic counselling , prenatal diagnosis and newborn screening.","About 6-8% of births worldwide involve a genetic or partly genetic anomaly; chromosomal anomalies explain ~11% of recurrent pregnancy loss in Moroccan couples."],"dp":[]},"genetics1-heredity:e2":{"s":1,"u":["Co-dominance: ABO; incomplete dominance: intermediate phenotype.","Allelic expression: dominance, incomplete dominance (intermediate phenotype), co-dominance (both expressed: ABO blood groups A and B)."],"dp":[]},"genetics1-heredity:e3":{"s":2,"u":["AD: vertical, 50%, both sexes; de novo, germline mosaicism, incomplete penetrance (retinoblastoma ~90%).","Pitfalls: de novo mutations (often paternal, age effect; e.g. achondroplasia), germline mosaicism (a normal parent can have several affected children; negative parental testing ≠ zero risk), incomplete penetrance (e.g. retinoblastoma ~90% : 10% of carriers never develop tumours, mimicking skipped generations; penetrance depends on age, modifier genes, environment), variable expressivity and pleiotropy (one gene, several traits; cleidocranial dysostosis).","Autosomal dominant : Aa × aa → 50% risk per pregnancy; vertical transmission; both sexes."],"dp":[]},"genetics1-heredity:e4":{"s":2,"u":["AD examples: achondroplasia, NF1, Marfan, ADPKD, osteogenesis imperfecta.","Examples: achondroplasia (FGFR3), polydactyly, hereditary angioedema (SERPING1), neurofibromatosis 1 (café-au-lait spots, neurofibromas, Lisch nodules), Marfan (FBN1: skeletal, aortic root dilation, ectopia lentis), osteogenesis imperfecta (COL1A1/2), ADPKD (PKD1/2), Charcot-Marie-Tooth 1A (PMP22 duplication)."],"dp":[]},"genetics1-heredity:e5":{"s":2,"u":["AR: horizontal, carrier parents, 25% risk, consanguinity; CF, thalassaemia, Wilson, SMA.","Autosomal recessive : affected are a/a ; parents usually healthy carriers ; Aa × Aa → 25% affected , 50% carriers, 25% non-carriers; horizontal pattern (siblings); both sexes; consanguinity increases risk (the child is consanguineous, not the marriage).","Examples: thalassaemias , albinism (OCA1/2), cystic fibrosis (CFTR), haemochromatosis (HFE), Wilson disease (ATP7B), xeroderma pigmentosum, spinal muscular atrophy (SMN1)."],"dp":[]},"genetics1-heredity:e10":{"s":3,"u":["Multifactorial: liability threshold; imprinting: parent-of-origin expression.","Multifactorial : many genes + environment, liability-threshold model , familial clustering without Mendelian ratios (cleft lip/palate, pyloric stenosis, clubfoot, diabetes, asthma, hypertension, schizophrenia).","Genomic imprinting : ~100-200 genes; only the maternal or paternal allele is expressed, set epigenetically by the sex of the transmitting parent and reset each generation."],"dp":[]},"genetics1-heredity:e6":{"s":3,"u":["XR: males, no father→son; haemophilia A/B, DMD, colour blindness.","X-linked recessive : mostly males (hemizygous); carrier females usually healthy; no father-to-son transmission ; skips generations.","Examples: haemophilia A (factor VIII, 80-85%) and B (factor IX, Christmas disease), Duchenne /Becker (~1 in 3,500-5,000 boys), colour blindness (~8% of men), Lesch-Nyhan, X-linked adrenoleukodystrophy."],"dp":[]},"genetics1-heredity:e7":{"s":3,"u":["XD: affected father → all daughters; fragile X, hypophosphataemic rickets.","Healthy father + carrier mother: 50% of sons affected, 50% of daughters carriers; affected father: all daughters carriers, no sons affected.","X-linked dominant : both sexes; affected father → all daughters , no sons; affected mother → 50% of children; often more severe or lethal in males."],"dp":[]},"genetics1-heredity:e8":{"s":3,"u":["Y-linked: father → all sons.","Y-linked (holandric) : father → all sons (SRY, AZF).","Healthy father + carrier mother: 50% of sons affected, 50% of daughters carriers; affected father: all daughters carriers, no sons affected."],"dp":[{"h":"Why X-linked recessive diseases skip to grandsons","t":"An affected man passes his X to all his daughters, who become healthy carriers because their second X compensates, and his Y to his sons, who are unaffected. Each carrier daughter then has a 50% chance of passing the mutated X to her sons, who are affected. The disease therefore appears in a grandfather and his grandsons, skipping the middle generation. Source: the lecture's X-linked recessive slides."}]},"genetics1-heredity:e9":{"s":3,"u":["Mitochondrial: maternal; heteroplasmy.","Mitochondrial : mtDNA 16,569 bp, 37 genes; maternal only ; both sexes, often more severe in males; heteroplasmy sets severity; multi-organ energy failure (muscle, nerve, brain, heart, eye)."],"dp":[]}},"meta":{"rw4z6s":{"a":"recall","vg":"genetics1-heredity:e0/recall/1"},"fjfrrt":{"a":"recall","vg":"genetics1-heredity:e1/recall/1"},"zy8tk0":{"a":"recall","vg":"genetics1-heredity:e2/recall/1"},"1fobit3":{"a":"recall","vg":"genetics1-heredity:e5/recall/1"},"cpvn5c":{"a":"recall","vg":"genetics1-heredity:e3/recall/1"},"112siss":{"a":"recall","vg":"genetics1-heredity:e3/recall/2"},"os40o7":{"a":"recall","vg":"genetics1-heredity:e3/recall/3"},"1toxtbe":{"a":"relationship","vg":"genetics1-heredity:e4/relationship/1"},"1dn5mh8":{"a":"recall","vg":"genetics1-heredity:e5/recall/1"},"fa89d8":{"a":"recall","vg":"genetics1-heredity:e5/recall/2"},"1q7nl8n":{"a":"recall","vg":"genetics1-heredity:e5/recall/3"},"11xsu7t":{"a":"recall","vg":"genetics1-heredity:e6/recall/1"},"1vifo28":{"a":"recall","vg":"genetics1-heredity:e8/recall/1"},"1vsxnya":{"a":"relationship","vg":"genetics1-heredity:e6/relationship/1"},"1ecqdu9":{"a":"recall","vg":"genetics1-heredity:e8/recall/2"},"ucsyl3":{"a":"recall","vg":"genetics1-heredity:e9/recall/1"},"1lci8x5":{"a":"recall","vg":"genetics1-heredity:e10/recall/1"}},"explRev":"6aac53af01b9"};
